# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">BOYLE YASASI (P - V) VE CHARLES YASASI (V - T) (10.1.9)</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. BOYLE YASASI (BASINÇ - HACİM)</text>\n  <rect x="55" y="74" width="250" height="32" rx="6" fill="#dbeafe" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="95" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">P₁ · V₁ = P₂ · V₂ = sabit  (n, T sabit)</text>\n  <text x="34" y="124" font-size="10.6" fill="#1e3a8a">• Sabit sıcaklıkta (izoterm) belli miktar gazın</text>\n  <text x="34" y="142" font-size="10.6" fill="#1e3a8a">  basıncı (P) ile hacmi (V) TERS ORANTILIDIR.</text>\n  <text x="34" y="162" font-size="10.6" fill="#1e3a8a">• Hacim yarıya inerse birim zamandaki çarpışma</text>\n  <text x="34" y="180" font-size="10.6" fill="#1e3a8a">  sayısı ve basınç 2 katına çıkar.</text>\n  <text x="34" y="198" font-size="10.4" font-weight="bold" fill="#1d4ed8">• P - V grafiği hiperbol (eğri); P·V - V grafiği yataydır.</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">2. CHARLES YASASI (HACİM - SICAKLIK)</text>\n  <rect x="395" y="74" width="250" height="32" rx="6" fill="#dcfce7" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="95" text-anchor="middle" font-size="13" font-weight="bold" fill="#14532d">V₁ / T₁ = V₂ / T₂ = sabit  (n, P sabit)</text>\n  <text x="374" y="124" font-size="10.6" fill="#14532d">• Sabit basınçta (ideal pistonlu kap) gazın hacmi (V)</text>\n  <text x="374" y="142" font-size="10.6" fill="#14532d">  ile mutlak sıcaklığı (T, Kelvin) DOĞRU ORANTILIDIR.</text>\n  <text x="374" y="162" font-size="10.6" fill="#14532d">• T(K) = t(°C) + 273 (Mutlak sıfır = 0 K = -273 °C).</text>\n  <text x="374" y="180" font-size="10.6" fill="#14532d">• Sıcaklık Kelvin cinsinden 2 katına çıkarsa hacim</text>\n  <text x="374" y="198" font-size="10.4" font-weight="bold" fill="#15803d">  2 katına çıkar, öz kütle (d = m/V) yarıya iner.</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">Gaz yasası hesaplamalarında sıcaklık daima Kelvin (T = °C + 273) birimine çevrilerek kullanılır!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">GAY-LUSSAC YASASI (P - T) VE AVOGADRO YASASI (V - n)</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">3. GAY-LUSSAC YASASI (BASINÇ - SICAKLIK)</text>\n  <rect x="55" y="74" width="250" height="32" rx="6" fill="#fde68a" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="180" y="95" text-anchor="middle" font-size="13" font-weight="bold" fill="#78350f">P₁ / T₁ = P₂ / T₂ = sabit  (n, V sabit)</text>\n  <text x="34" y="124" font-size="10.6" fill="#78350f">• Sabit hacimli (çelik/cam) kapta gazın basıncı (P)</text>\n  <text x="34" y="142" font-size="10.6" fill="#78350f">  ile mutlak sıcaklığı (T) DOĞRU ORANTILIDIR.</text>\n  <text x="34" y="162" font-size="10.6" fill="#78350f">• Sıcaklık arttıkça taneciklerin ortalama kinetik</text>\n  <text x="34" y="180" font-size="10.6" fill="#78350f">  enerjisi, hızı ve çarpışma şiddeti artar.</text>\n  <text x="34" y="198" font-size="10.4" font-weight="bold" fill="#92400e">• Örnek: Deodorant kutularının ateşe atılmaması.</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">4. AVOGADRO YASASI (HACİM - MOL SAYISI)</text>\n  <rect x="395" y="74" width="250" height="32" rx="6" fill="#f3e8ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="95" text-anchor="middle" font-size="13" font-weight="bold" fill="#581c87">V₁ / n₁ = V₂ / n₂ = sabit  (P, T sabit)</text>\n  <text x="374" y="124" font-size="10.6" fill="#581c87">• Aynı sıcaklık ve basınçta gazların hacmi (V) ile</text>\n  <text x="374" y="142" font-size="10.6" fill="#581c87">  madde miktarı (mol sayısı, n) DOĞRU ORANTILIDIR.</text>\n  <text x="374" y="162" font-size="10.6" fill="#581c87">• Normal Koşullarda (0 °C, 1 atm): 1 mol gaz = 22,4 L</text>\n  <text x="374" y="180" font-size="10.6" fill="#581c87">• Oda Koşullarında (25 °C, 1 atm): 1 mol gaz = 24,5 L</text>\n  <text x="374" y="198" font-size="10.4" font-weight="bold" fill="#6b21a8">• Örnek: Üflenen elastik balonun hacminin artması.</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">Sabit hacimli kapta gaz eklenirse basınç mol sayısıyla doğru orantılı artar: P₁ / n₁ = P₂ / n₂ (V, T sabit).</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">BİRLEŞTİRİLMİŞ GAZ DENKLEMİ VE BİLİMSEL SORGULAMA DEĞİŞKENLERİ</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#065f46">DENEYSEL DEĞİŞKENLERİN BELİRLENMESİ</text>\n  <text x="34" y="88" font-size="10.6" fill="#064e3b">• Bağımsız Değişken: Araştırmacının bizzat değiştirdiği</text>\n  <text x="34" y="106" font-size="10.3" fill="#064e3b">  etken (ör. Charles deneyinde ısıtılarak değiştirilen T).</text>\n  <text x="34" y="128" font-size="10.6" fill="#064e3b">• Bağımlı Değişken: Bağımsız değişkene bağlı olarak</text>\n  <text x="34" y="146" font-size="10.3" fill="#064e3b">  sonucu ölçülen özellik (ör. değişen gaz hacmi V).</text>\n  <text x="34" y="168" font-size="10.6" fill="#064e3b">• Kontrol Değişkeni: Deney boyunca sabit tutulan</text>\n  <text x="34" y="186" font-size="10.3" fill="#064e3b">  büyüklükler (ör. sabit tutulan P ve mol sayısı n).</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">GENEL GAZ BAĞINTISI VE GRAFİKLER</text>\n  <rect x="395" y="76" width="250" height="34" rx="6" fill="#ffedd5" stroke="#f97316" stroke-width="1.5"/>\n  <text x="520" y="98" text-anchor="middle" font-size="13" font-weight="bold" fill="#7c2d12">(P₁ · V₁) / (n₁ · T₁) = (P₂ · V₂) / (n₂ · T₂)</text>\n  <text x="374" y="130" font-size="10.6" fill="#7c2d12">• T(Kelvin) grafikleri orijinden (0 K noktasından)</text>\n  <text x="374" y="148" font-size="10.6" fill="#7c2d12">  başlayan doğrusal grafiklerdir.</text>\n  <text x="374" y="168" font-size="10.6" fill="#7c2d12">• t(°C) grafiklerinde ise doğru uzantısı yatay ekseni</text>\n  <text x="374" y="186" font-size="10.6" fill="#7c2d12">  -273,15 °C (mutlak sıfır) noktasında keser.</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">Sabit kalan değişkenler genel gaz denkleminden silindiğinde ilgili ikili gaz yasası doğrudan elde edilir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
